SELECT CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 600 THEN 'mid' ELSE 'low' END AS revenue_bucket, COUNT(i.quantity) AS quantity_count, MIN(i.quantity) AS min_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.units <> 26 GROUP BY CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 600 THEN 'mid' ELSE 'low' END ORDER BY quantity_count ASC;
